import React from 'react';

interface HeaderProps {
  username?: string;
  sector?: string;
}

const Header: React.FC<HeaderProps> = ({ username, sector }) => (
  <header className="h-[80px] bg-[#1e1e3f] border-b border-[#2d2d5f] z-50 flex flex-col justify-center px-6 flex-shrink-0">
    <div className="flex items-center justify-between">
      <div className="text-lg font-semibold text-blue-400">CyberSec Assessment Platform</div>
      <div className="text-sm text-gray-400">Assessment Session #2025-001</div>
    </div>
    {(username || sector) && (
      <div className="flex items-center gap-4 mt-2 text-sm text-gray-300">
        {username && (
          <span className="bg-blue-900/60 px-3 py-1 rounded-full font-medium">User: {username}</span>
        )}
        {sector && (
          <span className="bg-indigo-900/60 px-3 py-1 rounded-full font-medium">Sector: {sector}</span>
        )}
      </div>
    )}
  </header>
);

export default Header;
